final class NativeRampPartHostChecks {
 private static final BlockPos POS=new BlockPos(22888,100,22888),BAD=POS.east();private static final UUID ID=UUID.fromString("a4d98a75-4718-4dbb-9491-e0e165430009");private static Fixture block;private static BlockEntityType<NativeRampPartEntity> type;private static int checks;
 private static void need(boolean ok,String text){checks++;if(!ok)throw new AssertionError("Ramp part host: "+text);}
 private static final class Fixture extends NativeRampPartBlock {Fixture(){super(BlockBehaviour.Properties.of(),()->type);}protected MapCodec<Fixture> codec(){return MapCodec.unit(this);}public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return new NativeRampPartEntity(type,pos,state);}}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!System.getProperty("vandorlabs.transmitterPhase","").startsWith("ramp-host-"))return;var id=ResourceLocation.parse("vandorlabs:ramp_part_host_fixture");event.register(Registries.BLOCK,h->{block=new Fixture();h.register(id,block);});event.register(Registries.BLOCK_ENTITY_TYPE,h->{type=BlockEntityType.Builder.<NativeRampPartEntity>of((p,s)->new NativeRampPartEntity(type,p,s),block).build(null);h.register(id,type);});}}
 private static NativeRampPartData data(BlockPos pos){var state=Blocks.STONE.defaultBlockState();var material=new NativeRampPartMaterial(state,-1,-1,-1,0,false,false,new int[]{-1,-1,-1,-1,-1,-1});var origin=new NativeRampPartData.Origin(pos,8,material);var spec=new NativeRampGeometry.Spec(pos,Direction.NORTH,pos.getY(),0,3,8,0,1,0,-2,false,0,false,false,0,false,false,false,List.of(origin.geometry()));return new NativeRampPartData(spec,state,List.of(origin),new NativeRampPartData.Motion(5,100,0,1,32,true,0));}
 private static CompoundTag envelope(BlockPos pos){var tag=new CompoundTag();tag.putInt("NativeRampPartSchema",1);tag.putUUID("Operation",ID);tag.putInt("RootX",pos.getX());tag.putInt("RootY",pos.getY());tag.putInt("RootZ",pos.getZ());tag.put("NativeRampPartData",data(pos).write());return tag;}
 static void write(ServerLevel level){var stagedPos=POS.north(2);var staged=new NativeRampPartEntity(type,stagedPos,block.defaultBlockState());var prepared=staged.preparePublication(data(stagedPos),7,100);need(staged.getLevel()==null&&staged.publication()==null&&!staged.ownershipKnown(),"detached preparation does not initialize ownership");staged.stagePublication(ID,stagedPos,prepared);need(staged.getLevel()==null&&staged.operationId().equals(ID)&&staged.publication()==prepared,"complete detached body before world installation");try{staged.stagePublication(ID,stagedPos,prepared);throw new AssertionError("reused staged owner");}catch(IllegalStateException expected){}level.getChunkAt(POS);level.setBlock(POS,block.defaultBlockState(),18);var owner=(NativeRampPartEntity)level.getBlockEntity(POS);owner.loadWithComponents(envelope(POS),level.registryAccess());need(owner.ownershipKnown()&&owner.publication()!=null,"valid complete owner");blockChecks(level,owner);owner.installPart(ID,POS,data(POS));var initial=owner.publication();try{owner.installPart(ID,POS.above(65),data(POS));throw new AssertionError("far root installed");}catch(IllegalArgumentException expected){}need(owner.publication()==initial&&owner.belongs(ID,POS),"refused installation preserves complete prior owner");owner.prepare(116);var value=owner.publication();need(value.pose()==.5,"authoritative midpoint");need(owner.operationId().equals(ID)&&value.revision()==1&&value.observationTick()==116,"operation and ordered phase projection");need(!owner.acceptsObservation(ID,0,999)&&!owner.acceptsObservation(ID,1,115)&&owner.acceptsObservation(ID,1,116)&&owner.acceptsObservation(ID,1,117)&&owner.acceptsObservation(ID,2,0)&&owner.acceptsObservation(new UUID(3,7),0,0),"control revision and equal-control phase ordering");need(value.geometry().pieces().stream().map(p->p.box().move(POS)).toList().equals(owner.physicalBounds()),"world collision projection");need(java.util.concurrent.CompletableFuture.supplyAsync(()->owner.publication()==value&&owner.physicalBounds()==value.worldBoxes()).join(),"worker consumes immutable projection");java.util.concurrent.CompletableFuture.runAsync(()->owner.prepare(132)).join();need(owner.publication()==value,"worker refuses authoritative preparation");var dto=owner.getUpdateTag(level.registryAccess());need(dto.contains("NativeRampPartData")&&!dto.contains("Sources")&&!dto.contains("Items"),"public projection excludes physical ownership");level.setBlock(BAD,block.defaultBlockState(),18);var bad=(NativeRampPartEntity)level.getBlockEntity(BAD);var tag=envelope(BAD);tag.getCompound("NativeRampPartData").putInt("Schema",99);tag.putString("OpaquePart","retained");bad.loadWithComponents(tag,level.registryAccess());need(!bad.ownershipKnown()&&bad.publication()==null&&bad.physicalBounds()==null,"failed geometry cannot advertise known ownership");need(bad.saveWithoutMetadata(level.registryAccess()).equals(tag),"exact failed body retention");System.out.println("[vandorlabs][ramp-part-host] write PASS checks="+checks);}
 private static void blockChecks(ServerLevel level,NativeRampPartEntity moving){
  var pos=POS.south(2);level.setBlock(pos,block.defaultBlockState(),18);var part=(NativeRampPartEntity)level.getBlockEntity(pos);var data=data(pos);var old=data.spec();var spec=new NativeRampGeometry.Spec(pos,old.facing(),old.sourceY(),old.row(),2,old.treadPixels(),old.low(),old.high(),0,-2,false,0,true,false,0,false,false,false,old.origins());
  data=new NativeRampPartData(spec,data.original(),data.origins(),new NativeRampPartData.Motion(9,0,0,0,1,false,0));part.installPart(ID,pos,data);
  need(part.publication().stationaryTop(),"static full top prepared once");for(var face:Direction.values())need(part.getBlockState().isFaceSturdy(level,pos,face)==(face==Direction.UP),"Source attachment face "+face);
  var state=part.getBlockState();var actor=net.neoforged.neoforge.common.util.FakePlayerFactory.get(level,new com.mojang.authlib.GameProfile(new UUID(2,37),"RampPartHost"));actor.setPos(pos.getX()+.5,pos.getY()+1,pos.getZ()-2);actor.setGameMode(net.minecraft.world.level.GameType.CREATIVE);boolean handled=actor.gameMode.destroyBlock(pos);need(level.getBlockEntity(pos)==part&&level.getBlockState(pos).is(block),"real Creative game mode retains generated owner (handled receipt="+handled+")");actor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);actor.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.item.ItemStack(Blocks.STONE));level.setBlock(pos.above(),Blocks.AIR.defaultBlockState(),18);var hit=new net.minecraft.world.phys.BlockHitResult(new net.minecraft.world.phys.Vec3(pos.getX()+.5,pos.getY()+1,pos.getZ()+.5),Direction.UP,pos,false);need(actor.gameMode.useItemOn(actor,level,actor.getMainHandItem(),net.minecraft.world.InteractionHand.MAIN_HAND,hit).consumesAction()&&actor.getMainHandItem().getCount()==1&&level.getBlockState(pos.above()).isAir(),"surface consumes actual item click without placing or forwarding");var picked=block.getCloneItemStack(state,hit,level,pos,actor);need(picked.is(net.minecraft.world.item.Items.STONE)&&picked.getCount()==1&&!picked.has(net.minecraft.core.component.DataComponents.CUSTOM_DATA),"plain original pick has no source snapshot");
  var item=new net.minecraft.world.entity.item.ItemEntity(level,pos.getX()+.5,pos.getY()+.8,pos.getZ()+.5,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND));item.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);var context=net.minecraft.world.phys.shapes.CollisionContext.of(item);need(state.getCollisionShape(level,pos,context).bounds().maxY==1,"stationary collision unchanged");part.installPart(ID,pos,data.withMotion(new NativeRampPartData.Motion(10,0,0,0,1,true,0)));need(Math.abs(state.getCollisionShape(level,pos,context).bounds().maxY-.8)<1e-12,"moving support clips only shallow top overlap feet="+item.getBoundingBox().minY+" velocity="+item.getDeltaMovement()+" shape="+state.getCollisionShape(level,pos,context).bounds());
  var foreign=pos.west();level.setBlock(foreign,Blocks.STONE.defaultBlockState(),18);var obstacles=NativeRampRiders.obstacles(level,pos,item,new AABB(pos).inflate(2));need(obstacles.stream().noneMatch(b->b.intersects(new AABB(pos).deflate(.1)))&&obstacles.stream().anyMatch(b->b.equals(new AABB(foreign))),"real lazy world collision skips own-root only");
  level.setBlock(foreign,Blocks.AIR.defaultBlockState(),18);level.setBlock(pos,Blocks.AIR.defaultBlockState(),18);level.setBlock(pos,block.defaultBlockState(),18);level.removeBlockEntity(pos);need(state.getShape(level,pos).isEmpty()&&state.getCollisionShape(level,pos).isEmpty()&&!state.isFaceSturdy(level,pos,Direction.UP),"missing tile never substitutes a full housing");level.setBlock(pos,Blocks.AIR.defaultBlockState(),18);
 }
 static void read(ServerLevel level){var owner=(NativeRampPartEntity)level.getBlockEntity(POS);need(owner!=null&&owner.ownershipKnown()&&owner.data()!=null&&owner.publication().revision()==1&&owner.publication().observationTick()==116&&owner.publication().pose()==.5,"part restart");var bad=(NativeRampPartEntity)level.getBlockEntity(BAD);need(bad!=null&&!bad.ownershipKnown()&&bad.publication()==null&&bad.saveWithoutMetadata(level.registryAccess()).getString("OpaquePart").equals("retained"),"inert restart retention");System.out.println("[vandorlabs][ramp-part-host] read PASS checks="+checks);}
}
